@pytest.mark.parametrize("version", [v1001, v2168])
def test_transfer_is_packet_85(version):
    assert version.packets[85] is version.TransferPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_transfer_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_transfer_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_a_v1001_transfer_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.TransferPacket.from_bytes(V1001)


def test_a_v2168_transfer_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.TransferPacket.from_bytes(V2168_NO_GATHERING)
